func (this *Test_org_eclipse_swt_custom_CTabFolder) Test_dirtyIndicator_closesWhenCloseEnabled() {
	this.MakeCleanEnvironmentStyle(swt.CLOSE)
	this.shell.SetLayout(upcastswtFillLayoutToswtLayout(swt.NewFillLayout()))
	for i := int32(0); i < 3; i++ {
		var item *swt.CTabItem = swt.NewCTabItem(this.ctabFolder, swt.NONE)
		item.SetText(fmt.Sprintf("Tab %d", i))
		var content *swt.Label = swt.NewLabel(upcastswtCTabFolderToswtComposite(this.ctabFolder), swt.NONE)
		content.SetText(fmt.Sprintf("Content %d", i))
		item.SetControl(upcastswtLabelToswtControl(content))
	}
	this.ctabFolder.SetDirtyIndicatorStyle(true)
	this.ctabFolder.GetItem(0).SetShowDirty(true)
	this.ctabFolder.SetSelectionIndex(0)
	this.shell.SetSize(800, 400)
	SwtTestUtilOpenShell(this.shell)
	this.ProcessEvents()
	var dirtyItem *swt.CTabItem = this.ctabFolder.GetItem(0)
	func() {
		defer func() {
			r := recover()
			if r == nil {
				return
			}
			if false {
				var e error
				_ = e
				junit.Fail(fmt.Sprintf("Failed to access closeRect via reflection: %s", e.Error()))
			} else {
				panic(r)
			}
		}()
		var closeRectField any = jrt.ClassGetDeclaredField(reflect.TypeFor[*swt.CTabItem](), "closeRect")
		func() any { return nil }()
		var closeRectValue *swt.Rectangle = castanyToswtRectangle(closeRectField.(*jrt.Field).Get(dirtyItem.Impl()))
		junit.AssertTrue(closeRectValue.Width > 0 && closeRectValue.Height > 0, "closeRect should be allocated for dirty item")
		var mouseDown *swt.Event = swt.NewEvent()
		mouseDown.Type = swt.MouseDown
		mouseDown.Button = 1
		mouseDown.X = closeRectValue.X + closeRectValue.Width/2
		mouseDown.Y = closeRectValue.Y + closeRectValue.Height/2
		this.ctabFolder.NotifyListeners(swt.MouseDown, mouseDown)
		this.ProcessEvents()
		var mouseUp *swt.Event = swt.NewEvent()
		mouseUp.Type = swt.MouseUp
		mouseUp.Button = 1
		mouseUp.X = mouseDown.X
		mouseUp.Y = mouseDown.Y
		this.ctabFolder.NotifyListeners(swt.MouseUp, mouseUp)
		this.ProcessEvents()
		junit.AssertTrue(dirtyItem.IsDisposed(), "Dirty item should be disposed when close is enabled")
		junit.AssertEquals(int32(2), int32(this.ctabFolder.GetItemCount()), "Item count should decrease by 1")
	}()
}

// j2go: instanceof helper for swt.Rectangle and its subclasses within the translated set.
func rectangleImplAsRectangle(x any) (*swt.Rectangle, bool) {
	switch v := x.(type) {
	case *swt.Rectangle:
		if v == nil {
			return nil, false
		}
		return v, true
	case *swt.Rectangle_OfFloat:
		if v == nil {
			return nil, false
		}
		return &v.Rectangle, true
	case *swt.Rectangle_WithMonitor:
		if v == nil {
			return nil, false
		}
		return &v.Rectangle, true
	}
	if l, ok := x.(interface{ AsRectangle() *swt.Rectangle }); ok {
		return l.AsRectangle(), true
	}
	return nil, false
}

func castanyToswtRectangle(x any) *swt.Rectangle {
	if x == nil {
		return nil
	}
	v, ok := rectangleImplAsRectangle(x)
	if !ok {
		panic("java.lang.ClassCastException: swt.Rectangle")
	}
	return v
}
